scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

head.script:
scwin.trigger1_onclick = function(e) {
    dataList_menu.modifyRowStatus(1, "C");
};
scwin.gridView1_oncellclick = function(row, col) {};
scwin.gridView1_onviewchange = function(info) {
    if (info.colIndex == 0) {
        var realIdx = gridView1.getRealRowIndex(info.rowIndex);
        console.log(info);
        if (info.newValue == '1') {
            console.log('ccc');
            console.log(info.rowIndex);
            console.log(realIdx);
            dataList_menu.modifyRowStatus(realIdx, "C");
        } else {
            console.log('rrr');
            dataList_menu.modifyRowStatus(realIdx, "R");
        }
    }
};
scwin.__isIconShow = function() {
    var el = WebSquare.wUnit.getDomById($p.id + 'gridView1_body_tbody').getElementsByTagName('tr')[2];
    return el.childNodes[1].getAttribute("class") == "gridBodyDefault gridBodyDefault_rowStatus w2grid_rowStatus_C";
}
scwin.__triggerClick = function() {
    return WebSquare.wUnit.getJq(checkBox).click();
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 3번째 row의 체크박스를 클릭한다.
    //1. Execute the sample file and click the check box of the third row.
    WebSquare.wUnit.addCommand("set", "scwin.__triggerClick()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 1. 체크박스 왼쪽컬럼에 +기호가 보여진다.(이전에는 보여지지 않음)
    //1. The + sign appears in the left column of the checkbox.(Previously not shown)
    WebSquare.wUnit.addCommand("assert", "scwin.__isIconShow()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
